import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
import { setImmediate as flush } from 'node:timers/promises';
import { NativeBridge } from '/Users/jordanknight/pi-hacking/fs3-copilot-native-runtime/.copilot/extensions/pij/store.mjs';
const rows = (await readFile(process.env.PIJ_TRACE, 'utf8')).trim().split('\n').map(JSON.parse);
const root = rows.find(e => e.type === 'user.message');
const idle = rows.find(e => e.type === 'session.idle');
const reports = [];
const registration = {id:'pij-replay',harness_session:'replay-session',pid:1,proc_start:1};
const bridge = new NativeBridge({registration, native:{send:async()=>root.messageId}, client:{request:async()=>1}, journal:{load:async()=>undefined,begin:async()=>true,accept:async()=>{}}, report:e=>reports.push(e)});
await bridge.deliver({job_id:1,message:{msg_id:'replay-message',from:'pij-sender',to:'pij-replay',body:'metadata-only replay'},native_consumer:{native_session:'replay-session',pid:1,proc_start:1}});
const waiting = bridge.waitForCompletion().then(()=>true,error=>{if(!bridge.controller.signal.aborted)throw error;return false;});
for(const e of rows) bridge.completion.observe({...e,data:{messageId:e.messageId,interactionId:e.interactionId,turnId:e.turnId}});
await flush();
const result = {events:rows.length,root_seen:bridge.completion.descendants.has(root.id),idle_received:true,idle_parent_seen_in_input:rows.some(e=>e.id===idle.parentId),idle_parent_in_descendants:bridge.completion.descendants.has(idle.parentId),terminal:bridge.completion.terminal??null,completion_reported:reports.some(e=>e.kind==='native-completed'),acknowledgements:reports.filter(e=>e.kind==='inbox-acknowledged').length};
assert.equal(result.root_seen,true); assert.equal(result.idle_parent_seen_in_input,true); assert.equal(result.idle_parent_in_descendants,false); assert.equal(result.terminal,null); assert.equal(result.completion_reported,false); assert.equal(result.acknowledgements,1);
bridge.stop(); assert.equal(await waiting,false);
console.log(JSON.stringify({...result,stopped_cleanly:true}));
